/* ===== 三五中文网 xkushu.org 专用 =====
 * 纯计算，不发网络请求；不引用 baseUrl / java / book（技能教训 23、40）
 * 站点：杰奇 CMS（zww 模板），UTF-8，仅 http
 */

/* ---------- 基础工具 ---------- */
function kbTrim(s) {
    return String(s === null || s === undefined ? '' : s).replace(/^[\s\u00a0\u3000]+|[\s\u00a0\u3000]+$/g, '');
}

function kbEsc(s) {
    return String(s === null || s === undefined ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;')
        .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function kbUnescape(s) {
    var t = String(s === null || s === undefined ? '' : s);
    t = t.replace(/&nbsp;/gi, ' ').replace(/&ensp;/gi, ' ').replace(/&emsp;/gi, '\u3000');
    t = t.replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"');
    t = t.replace(/&apos;/gi, "'").replace(/&#39;/g, "'").replace(/&amp;/gi, '&');
    t = t.replace(/&#x([0-9a-f]+);/gi, function (m, h) { return String.fromCharCode(parseInt(h, 16)); });
    t = t.replace(/&#(\d+);/g, function (m, d) { return String.fromCharCode(parseInt(d, 10)); });
    return t;
}

function kbAbs(u) {
    var s = kbTrim(u);
    if (!s) return '';
    if (/^https?:\/\//i.test(s)) return s;
    if (s.indexOf('//') === 0) return 'http:' + s;
    return 'http://www.xkushu.org' + (s.charAt(0) === '/' ? '' : '/') + s;
}

function kbStatus(v) {
    var t = kbTrim(kbUnescape(v));
    if (!t) return '';
    if (/完结|完本|全本|已完成/.test(t)) return '完结';
    if (/连载|連載|未完/.test(t)) return '连载';
    return '';
}

/* 列表与详情共用的日期处理：站点列表给 26-11-22（两位年），详情页给 2026-11-21 22:59:00 */
function xkDate(v) {
    var s = kbTrim(v);
    if (!s) return '';
    var m = s.match(/(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
    if (m) {
        return m[1] + '-' + (m[2].length < 2 ? '0' + m[2] : m[2]) + '-' + (m[3].length < 2 ? '0' + m[3] : m[3]);
    }
    m = s.match(/^(\d{2})[-/](\d{1,2})[-/](\d{1,2})/);
    if (m) {
        return '20' + m[1] + '-' + (m[2].length < 2 ? '0' + m[2] : m[2]) + '-' + (m[3].length < 2 ? '0' + m[3] : m[3]);
    }
    return '';
}

/* ---------- 字数 ----------
 * 列表给 "3161K"（千字），详情给 "5958028字"
 */
function kbWordsStr(v) {
    var t = kbTrim(v).replace(/,/g, '');
    if (!t) return '';
    var m = t.match(/^([\d.]+)\s*[Kk]$/);
    if (m) return (parseFloat(m[1]) / 10).toFixed(1) + '万字';
    m = t.match(/^([\d.]+)\s*万\s*字?$/);
    if (m) return m[1] + '万字';
    m = t.match(/^([\d.]+)\s*字$/);
    if (m) {
        var n1 = parseFloat(m[1]);
        return n1 >= 10000 ? (n1 / 10000).toFixed(1) + '万字' : Math.round(n1) + '字';
    }
    m = t.match(/^([\d.]+)$/);
    if (m) {
        var n2 = parseFloat(m[1]);
        return n2 >= 10000 ? (n2 / 10000).toFixed(1) + '万字' : Math.round(n2) + '字';
    }
    return t;
}

/* ---------- 列表字段 ---------- */

/* 封面：由书籍相对地址 /35zwhtml/{a}/{id}/ 拼 /35zwimage/{a}/{id}/{id}s.jpg */
function xkCover(u) {
    var s = kbTrim(u);
    var m = s.match(/\/35zwhtml\/(\d+)\/(\d+)/);
    if (!m) {
        m = s.match(/\/zwwinfo\/(\d+)\/(\d+)\.htm/);
        if (!m) return '';
    }
    return 'http://www.xkushu.org/35zwimage/' + m[1] + '/' + m[2] + '/' + m[2] + 's.jpg';
}

/* 列表书名可能带多余空白 */
function xkListName(v) {
    return kbTrim(kbUnescape(v)).replace(/\s+/g, ' ');
}

/* ---------- 详情页 ---------- */

/* 作者：作&nbsp;&nbsp;&nbsp; 者：<a href="/author/xx">名字</a> */
function xkAuthor(html) {
    var t = String(html === null || html === undefined ? '' : html);
    /* 站点 "作&nbsp;&nbsp;&nbsp; 者：" —— nbsp 实体与普通空格都要吃掉 */
    var m = t.match(/作(?:&nbsp;|[\s\u00a0])*者[：:]\s*<a[^>]*>([\s\S]*?)<\/a>/);
    if (m) return kbTrim(kbUnescape(m[1]));
    m = t.match(/>\s*作(?:&nbsp;|[\s\u00a0])*者[：:]\s*([^<|\n]{1,40})/);
    return m ? kbTrim(kbUnescape(m[1])) : '';
}

/* 分类 + 状态：类别：玄幻魔法 / 文章状态：连载中 */
function xkKind(html) {
    var t = String(html === null || html === undefined ? '' : html);
    var out = [];
    /* 页面顶部的「小说类别:」下拉框也会命中，逐个试、取第一个非空 */
    var re = /类(?:&nbsp;|[\s\u00a0])*别[：:][ \t]*([^<\r\n]{1,20})/g, m;
    while ((m = re.exec(t))) {
        var c = kbTrim(kbUnescape(m[1])).replace(/[，,。.]$/, '');
        if (c && c.length > 1) { out.push(c); break; }
    }
    var s = t.match(/文章状态[：:][ \t]*([^<\r\n]{1,10})/);
    if (s) {
        var v = kbStatus(s[1]);
        if (v) out.push(v);
    }
    return out.join(',');
}

/* 字数：全文长度：5958028字 */
function xkWords(html) {
    var t = String(html === null || html === undefined ? '' : html);
    var m = t.match(/全文长度[：:]\s*([\d.,]+\s*[Kk万亿]?\s*字?)/);
    if (!m) return '';
    return kbWordsStr(m[1]);
}

/* 最后更新：2026-11-21 22:59:00 */
function xkUpdateTime(html) {
    var t = String(html === null || html === undefined ? '' : html);
    var m = t.match(/最后更新[：:]\s*([\d\-\/ :]{8,25})/);
    return m ? xkDate(m[1]) : '';
}

/* 最近章节：span 后紧接 a，取 a 的文本 */
function xkLastChapter(html) {
    var t = String(html === null || html === undefined ? '' : html);
    var m = t.match(/最近章节[：:]?\s*<\/span>\s*<a[^>]*>([\s\S]*?)<\/a>/);
    if (m) return kbTrim(kbUnescape(m[1])).replace(/<[^>]+>/g, '');
    m = t.match(/最新章节[：:]?\s*<\/span>\s*<a[^>]*>([\s\S]*?)<\/a>/);
    return m ? kbTrim(kbUnescape(m[1])) : '';
}

/* 简介：内容简介：</span> …… <span class="hottext">作品关键字：</span>
 * 段落用 2 个以上 &nbsp; 分隔；详情页简介区不自动缩进，每段手加两个全角空格
 */
function xkIntro(html) {
    var t = String(html === null || html === undefined ? '' : html);
    var m = t.match(/内容简介[：:]\s*<\/span>([\s\S]*?)<span class="hottext">/);
    if (!m) m = t.match(/内容简介[：:]([\s\S]{0,4000}?)(?:<span class="hottext">|<\/td>)/);
    if (!m) return '';
    var s = m[1];
    s = s.replace(/<br\s*\/?>/gi, '\n');
    s = s.replace(/(?:&nbsp;|\u00a0){2,}/gi, '\n');     // 两个以上 nbsp = 段落分隔
    s = s.replace(/<[^>]+>/g, '');
    s = kbUnescape(s).replace(/\u00a0/g, ' ');
    var lines = s.split('\n'), out = [], i, l;
    for (i = 0; i < lines.length; i++) {
        l = kbTrim(lines[i]);
        if (l && l.length > 1) out.push('\u3000\u3000' + l);
    }
    return out.join('\n');
}

/* 目录地址：详情页里 <a href="/35zwhtml/89/89453/"><h1>书名</h1></a> */
function xkTocUrl(html) {
    var t = String(html === null || html === undefined ? '' : html);
    var m = t.match(/href="(\/35zwhtml\/\d+\/\d+\/)"[\s\S]{0,120}?<h1>/);
    if (m) return 'http://www.xkushu.org' + m[1];
    m = t.match(/\/35zwhtml\/(\d+)\/(\d+)\//);
    return m ? 'http://www.xkushu.org/35zwhtml/' + m[1] + '/' + m[2] + '/' : '';
}

/* ---------- 正文 ---------- */

/* #content 内是 <br/> 分段的裸文本，段前 4 个 &nbsp;
 * 开头有一个 <div class="gg_read_content_up"><script>…</script></div> 广告占位
 */
function xkContent(html) {
    var t = String(html === null || html === undefined ? '' : html);
    if (!t) return '<p>△ 正文获取失败</p>';
    /* 站方未录完的新章：页面写「正在手打中，请稍等片刻，内容更新后请重新刷新」 */
    var typing = /正在手打中|请稍等片刻[，,]?\s*内容更新后/.test(t);

    // ① 脚本、广告占位块、注释
    t = t.replace(/<script[\s\S]*?<\/script>/gi, '');
    t = t.replace(/<div[^>]*class="[^"]*gg_read_content[^"]*"[^>]*>[\s\S]*?<\/div>/gi, '');
    t = t.replace(/<!--[\s\S]*?-->/g, '');

    // ② 插图保留（正文偶有插图）
    var imgs = [];
    t = t.replace(/<img[^>]*src\s*=\s*["']([^"']+)["'][^>]*>/gi, function (m, src) {
        imgs.push(kbAbs(src));
        return '\u0001IMG' + (imgs.length - 1) + '\u0001';
    });

    // ③ 分段
    t = t.replace(/<br\s*\/?>/gi, '\n');
    t = t.replace(/<\/(p|div|h[1-6]|li|tr|dd)>/gi, '\n');
    t = t.replace(/<[^>]+>/g, '');
    t = kbUnescape(t).replace(/\u00a0/g, ' ');

    // ④ 逐行清理
    var lines = t.split('\n'), out = [], i, l, h;
    for (i = 0; i < lines.length; i++) {
        l = kbTrim(lines[i]);
        if (!l) continue;
        if (/^[(（]?(本章未完|未完待续|请记住本站|最新网址|手机阅读|加入书签)[^。]{0,40}[)）]?$/.test(l)) continue;
        /* 水印：只在疑似行上做全角拉丁归一，不碰正文的全角标点 */
        h = l;
        if (/三五中文网|３５|35zww|ｗｗｗ/i.test(l)) {
            h = l.replace(/[\uFF57\uFF13\uFF15\uFF5A\uFF0E\uFF43\uFF4F\uFF4D]/g, function (c) {
                return String.fromCharCode(c.charCodeAt(0) - 0xFEE0);
            });
        }
        /* 段尾半截水印：(三五中文网 ; (35zww ; (www.35zww.com */
        h = h.replace(/[（(]\s*三五中文网\s*$/, '');
        h = h.replace(/[（(]\s*(?:www\.)?35zww[.．]?[a-z]*\s*$/, '');
        h = kbTrim(h);
        if (!h) continue;
        if (/^[（(\[]?\s*(?:https?:\/\/)?(?:www\.)?35zww\.(?:com|net|org|cc)\s*[)）\]]?$/i.test(h)) continue;
        if (/^(?:https?:\/\/)?(?:www\.)?xkushu\.(?:org|com)/i.test(h)) continue;
        if (/三五中文网/.test(h) && h.length < 40) continue;
        /* 站方「未录完」提示行，不是正文 */
        if (/正在手打中|请稍等片刻|内容更新后[，,]?\s*请重新刷新/.test(h)) continue;
        l = h;
        // 图片占位还原
        l = l.replace(/\u0001IMG(\d+)\u0001/g, function (m, n) { return '<img src="' + imgs[parseInt(n, 10)] + '">'; });
        if (/^<img /.test(l)) { out.push('<p>' + l + '</p>'); continue; }
        if (l.length < 2) continue;
        if (/^[*\-—=~·．.。_\s]{2,}$/.test(l)) continue;   // 纯符号分隔行
        out.push('<p>' + kbEsc(l) + '</p>');
    }
    if (typing) {
        var tl = 0, j;
        for (j = 0; j < out.length; j++) tl += out[j].length;
        /* 只剩几行残句时不冒充正文，直接给提示 */
        if (out.length < 3 || tl < 300) {
            return '<p>△ 本章站点尚未录入完整（页面提示「正在手打中」），稍后刷新或换源重试</p>';
        }
        out.push('<p>△ 本章站点尚未录入完整（页面提示「正在手打中」），稍后刷新或换源重试</p>');
        return out.join('\n');
    }
    if (!out.length) return '<p>△ 本章内容为空，可能为付费章节或需要登录</p>';
    return out.join('\n');
}

/* 目录异常兜底：返回一行诊断节点，避免 TocEmptyException 整页报错 */
function xkTocFallback() {
    return '<div class="xk-toc-err">△ 目录解析异常</div>';
}
